Thuật toán sinh xâu nhị phân kế tiếp theo thứ tự từ điển.
Xâu đầu 00…0; xâu cuối 11…1.
Từ x = (x₁,…,x_n): tìm i lớn nhất sao cho x[i] = 0; nếu không có thì x là xâu cuối ⇒ dừng. Đặt x[i] = 1 và mọi x[j] = 0 với j > i. (Chính là phép cộng 1 trong hệ nhị phân.)

Mã C/C++:
#include <bits/stdc++.h>
using namespace std;
int main(){
    int n; cin >> n;
    vector<int> x(n, 0);            // xâu đầu tiên 00...0
    while(true){
        for(int b : x) cout << b; cout << "\n";
        int i = n - 1;
        while(i >= 0 && x[i] == 1) x[i--] = 0;   // đổi các bit 1 cuối thành 0
        if(i < 0) break;                          // hết: xâu 11...1 đã in
        x[i] = 1;                                 // bit 0 phải nhất đổi thành 1
    }
}

